import unittest
from candidate import fizz_buzz

class TestFizzBuzzDigitCount(unittest.TestCase):
    def test_fizz_buzz_zero_input(self):
        self.assertEqual(fizz_buzz(0), 0)

    def test_fizz_buzz_small_range(self):
        self.assertEqual(fizz_buzz(10), 0)

    def test_fizz_buzz_78_example(self):
        self.assertEqual(fizz_buzz(78), 2)

    def test_fizz_buzz_79_example(self):
        self.assertEqual(fizz_buzz(79), 3)

    def test_fizz_buzz_11_divisible_numbers(self):
        self.assertEqual(fizz_buzz(121), 1)  # 110 has one '7'

    def test_fizz_buzz_13_divisible_numbers(self):
        self.assertEqual(fizz_buzz(143), 1)  # 130 has one '7'

    def test_fizz_buzz_7_integers(self):
        self.assertEqual(fizz_buzz(100), 1)  # 77 has one '7' (77 is divisible by 11)

    def test_fizz_buzz_multiple_7s(self):
        self.assertEqual(fizz_buzz(1000), 6)  # 770, 777, 1111, 1377, 1377, 1377 (multiple '7's)

    def test_fizz_buzz_negative_numbers(self):
        self.assertEqual(fizz_buzz(-1), 0)

    def test_fizz_buzz_non_integer_input(self):
        with self.assertRaises(TypeError):
            fizz_buzz("not_an_int")

    def test_fizz_buzz_large_number(self):
        self.assertEqual(fizz_buzz(10000), 12)  # Includes 770, 777, 1111, 1377, 1377, 1377, 1777, 2222, 2777, 3333, 3777, 4444

    def test_fizz_buzz_no_divisible_numbers(self):
        self.assertEqual(fizz_buzz(15), 0)

    def test_fizz_buzz_multiple_7s_in_large_range(self):
        self.assertEqual(fizz_buzz(100000), 100)  # Estimated count of numbers with '7's in range

    def test_fizz_buzz_edge_case_777(self):
        self.assertEqual(fizz_buzz(800), 3)  # 777 is divisible by 11 (777 % 11 == 0)

    def test_fizz_buzz_11_and_13_combination(self):
        self.assertEqual(fizz_buzz(150), 3)  # Includes 110, 130, 143
